# ── c-sale-004 · 非法金额被拒（负/零/非数） · protects=['recordSale', 'server/domain.mjs']
def test_2_c_sale_004(api):
    """负/零/非数金额出库被拒且状态不变"""
    # 依据：surface=付款与货权 / invariant=非法金额被拒（负/零/非数）
    st = api.state()["body"]
    avail = next((i for i in st["items"] if i.get("status") == "AVAILABLE"), None)
    assert avail, "没有可出库的货品，前置数据不满足"
    seller = next((p["id"] for p in st["partners"] if p["id"] != avail.get("ownerPartnerId")), None)
    assert seller, "找不到非货权人的销售者"
    sig = "data:image/png;base64,QAAGENT"
    for bad in [-1, 0, "abc"]:
        r = api.post("/api/sale", {
            "inventoryItemId": avail["id"], "sellerPartnerId": seller,
            "dealPrice": bad, "managerSignature": sig, "sellerSignature": sig,
        })
        assert_rejected(r, why="出库金额为 %r 必须被拒绝" % (bad,))
        after = next(i for i in api.state()["body"]["items"] if i["id"] == avail["id"])
        assert after.get("status") == "AVAILABLE", "被拒绝的出库不得改动状态，实际=" + str(after.get("status"))

